# nginx: TLS termination, CSP, and reverse proxying
server {
  listen 443 ssl;
  server_name app.example.com;

  add_header Content-Security-Policy "default-src 'self'; script-src 'self' 'nonce-r4nd0m'" always;

  location /api/ {
    proxy_pass http://internal-api:8080/;
    proxy_set_header X-Forwarded-For $remote_addr;
    proxy_set_header X-Forwarded-Proto https;
  }
}
